#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
// 参数是非空数组，必须选一段连续且至少含一个元素的子数组。
int maxSubArray(int*nums,int numsSize) {
    int cur=nums[0],best=cur;
    for(int i=1;i<numsSize;i++) {
        // cur 表示当前结尾的最佳段和；起点也允许是当前元素。
        cur=cur>0?cur+nums[i]:nums[i];
        if(cur>best)best=cur;
    }
    // best 保存所有结束位置中的最大和，不能被较差的当前段覆盖。
    return best;
}
int main(void) {
    int n;
    scanf("%d",&n);
    int*a=malloc(n*sizeof(int));
    for(int i=0;i<n;i++)scanf("%d",&a[i]);
    printf("%d\n",maxSubArray(a,n));
    free(a);
    return 0;
}

